dir:


































  &DefaultButton;




function dir$dmlinegoi(p){
  this.constructor(p);
}
dir$dmlinegoi.prototype = new DirEvent();
dir$dmlinegoi.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmlinegoi.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmlinegoiDisabledMasterField(p, g);

}

function dir$dmlinegoiDisabledMasterField(p, g){

  if(p.valForm('ma_line').trim() != '')
  {
    p.setDisabled('ma_line', true);
  }
  else
  {
    p.setDisabled('ma_line', false);
  }
}






				.control-label.ma_line, .control-label.ten_line{
					color: #499b98;
				}







